package com.luxora.commerce.checkout.service;
import com.luxora.commerce.checkout.dto.*; import com.luxora.commerce.promotion.service.PromotionService; import java.math.BigDecimal; import java.util.List;
public record CheckoutCalculation(List<CheckoutCalculationItem> items,ShippingAddressResponse shippingAddress,BigDecimal subtotal,BigDecimal shippingFee,BigDecimal tax,BigDecimal discount,BigDecimal grandTotal,String currency,PromotionService.AppliedPromotion promotion){ public CheckoutPreviewResponse toPreviewResponse(){return new CheckoutPreviewResponse(items.stream().map(i->new CheckoutPreviewItemResponse(i.productId(),i.variantId(),i.slug(),i.name(),i.sku(),i.color(),i.storage(),i.imageUrl(),i.unitPrice(),i.quantity(),i.lineTotal())).toList(),shippingAddress,subtotal,shippingFee,tax,discount,grandTotal,currency,promotion.response());}}